INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-092', '{B}', 'Circula con un turismo con remolque; Â¿puede entrar en una vÃ­a con esta seÃ±al?', NULL, 'La seÃ±al permite el acceso al conjunto indicado en la pregunta cuando el remolque es de un solo eje.', true, '2026-10-07 07:20:11.542', '2026-10-07 07:20:11.542');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-093', '{A1,A2,A,B,C,D}', 'El consumo de cannabis afecta al comportamiento del conductor porque...', NULL, 'El cannabis puede aumentar el tiempo de reacciÃ³n y deteriorar la capacidad de respuesta ante los riesgos.', true, '2026-10-07 07:20:11.621', '2026-10-07 07:20:11.621');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-097', '{A1,A2,A,B,C,D}', 'Factores variables como la cantidad y la calidad del sueÃ±o, el consumo de medicamentos sedantes o la monotonÃ­a en la conducciÃ³n, Â¿afectan por igual a todos los conductores?', NULL, 'Los efectos de estos factores dependen de las caracterÃ­sticas y circunstancias de cada persona.', true, '2026-10-07 07:20:11.72', '2026-10-07 07:20:11.72');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-098', '{A1,A2,A,B,C,D}', 'En vÃ­a urbana, cuando utilice el carril que mÃ¡s convenga a su destino, Â¿puede abandonar dicho carril?', NULL, 'Puede abandonar ese carril para realizar determinadas maniobras, como cambiar de direcciÃ³n, adelantar, parar o estacionar.', true, '2026-10-07 07:20:11.739', '2026-10-07 07:20:11.739');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-099', '{A1,A2,A,B,C,D}', 'En una vÃ­a urbana, Â¿debe tocar el claxon para advertir que va a realizar un adelantamiento?', NULL, 'En una vÃ­a urbana no debe utilizarse el claxon para advertir un adelantamiento en este supuesto.', true, '2026-10-07 07:20:11.758', '2026-10-07 07:20:11.758');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-100', '{A1,A2,A,B,C,D}', 'Circula con la luz de largo alcance y se acerca a un vehÃ­culo que circula a menor velocidad en su mismo sentido de la marcha; Â¿debe sustituir la luz de carretera por la de corto alcance?', NULL, 'Debe cambiar a corto alcance para evitar deslumbrar al conductor del vehÃ­culo que circula delante.', true, '2026-10-07 07:20:11.775', '2026-10-07 07:20:11.775');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-101', '{A1,A2,A,B,C,D}', 'Si un conductor inicia un adelantamiento y se producen circunstancias que hacen difÃ­cil finalizar la maniobra...', NULL, 'Si la maniobra se complica, debe regresar a su carril cuando sea posible y evitar crear peligro.', true, '2026-10-07 07:20:11.794', '2026-10-07 07:20:11.794');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-102', '{A1,A2,A,B,C,D}', 'Â¿CuÃ¡l es una de las infracciones que cometen los conductores con mayor riesgo para los peatones?', NULL, 'No respetar la prioridad de los peatones en los pasos seÃ±alizados genera un riesgo especialmente elevado.', true, '2026-10-07 07:20:11.81', '2026-10-07 07:20:11.81');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-103', '{A1,A2,A,B,C,D}', 'Â¿QuiÃ©n estÃ¡ obligado a cuidar de que los pasajeros de un vehÃ­culo mantengan la posiciÃ³n adecuada para garantizar la seguridad?', NULL, 'El conductor debe velar por que los pasajeros mantengan una posiciÃ³n segura.', true, '2026-10-07 07:20:11.827', '2026-10-07 07:20:11.827');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-104', '{A1,A2,A,B,C,D}', 'Si un vehÃ­culo de la policÃ­a de trÃ¡fico se sitÃºa detrÃ¡s de usted y enciende un dispositivo con una luz roja destelleante hacia delante, Â¿quÃ© debe hacer?', NULL, 'La luz roja destelleante dirigida hacia delante indica al conductor que debe detenerse y seguir las instrucciones del agente.', true, '2026-10-07 07:20:11.843', '2026-10-07 07:20:11.843');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-105', '{A1,A2,A,B,C,D}', 'Â¿Es peligroso conducir cuando los rayos de sol caen de forma directa sobre los ojos del conductor?', NULL, 'El deslumbramiento solar puede reducir la capacidad de distinguir correctamente la vÃ­a, seÃ±ales y otros usuarios.', true, '2026-10-07 07:20:11.86', '2026-10-07 07:20:11.86');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-106', '{B,C,D}', 'A un turismo, Â¿le estÃ¡ permitido circular si tiene roto el espejo retrovisor exterior izquierdo?', NULL, 'No puede circular si el defecto impide al conductor ver correctamente la circulaciÃ³n posterior.', true, '2026-10-07 07:20:11.881', '2026-10-07 07:20:11.881');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-107', '{A1,A2,A,B,C,D}', 'Â¿QuÃ© es un microsueÃ±o?', NULL, 'Es un episodio muy breve de sueÃ±o involuntario que puede aparecer sin que el conductor sea consciente.', true, '2026-10-07 07:20:11.903', '2026-10-07 07:20:11.903');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-108', '{A1,A2,A,B,C,D}', 'En una retenciÃ³n en la que estÃ¡n los vehÃ­culos detenidos, Â¿estÃ¡ permitido usar el telÃ©fono mÃ³vil?', NULL, 'La detenciÃ³n en una retenciÃ³n no permite utilizar el telÃ©fono manualmente; solo se admite el uso permitido de manos libres sin auriculares.', true, '2026-10-07 07:20:11.924', '2026-10-07 07:20:11.924');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-109', '{A1,A2,A,B,C,D}', 'Una luz verde en forma de flecha apuntando hacia abajo en un semÃ¡foro de carril...', NULL, 'La flecha verde permite utilizar el carril, pero no elimina las reglas generales de prioridad.', true, '2026-10-07 07:20:11.947', '2026-10-07 07:20:11.947');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-110', '{A1,A2,A,B,C,D}', 'Entre la puesta y la salida del sol, Â¿puede encender la luz de largo alcance en caso de niebla?', NULL, 'En condiciones de niebla puede utilizarse la luz de carretera siempre que no deslumbre a otros usuarios.', true, '2026-10-07 07:20:11.963', '2026-10-07 07:20:11.963');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-111', '{A1,A2,A,B,C,D}', 'En este paso para peatones, si no funciona el semÃ¡foro, Â¿es obligatorio ceder el paso a los peatones que intenten cruzar?', NULL, 'En un paso para peatones seÃ±alizado, los peatones tienen prioridad en las condiciones establecidas.', true, '2026-10-07 07:20:11.981', '2026-10-07 07:20:11.981');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-112', '{A1,A2,A}', 'En la ficha de inspecciÃ³n tÃ©cnica de esta motocicleta figura que tiene estructura de autoprotecciÃ³n y cinturÃ³n de seguridad. Â¿Puede conducirla sin utilizar el casco de protecciÃ³n?', NULL, 'Cuando el vehÃ­culo dispone de estructura de autoprotecciÃ³n y cinturÃ³n de seguridad conforme a su homologaciÃ³n, se aplica la excepciÃ³n indicada.', true, '2026-10-07 07:20:11.996', '2026-10-07 07:20:11.996');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-113', '{A1,A2,A,B,C,D}', 'Si quiere abandonar una autovÃ­a, Â¿en quÃ© momento debe entrar en el carril de deceleraciÃ³n?', NULL, 'Debe incorporarse al carril de deceleraciÃ³n lo antes posible para reducir la velocidad fuera del carril principal.', true, '2026-10-07 07:20:12.01', '2026-10-07 07:20:12.01');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-114', '{A1,A2,A,B,C,D}', 'Â¿EstÃ¡ permitido estacionar en doble fila?', NULL, 'El estacionamiento en doble fila estÃ¡ prohibido.', true, '2026-10-07 07:20:12.027', '2026-10-07 07:20:12.027');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-115', '{A1,A2,A,B,C,D}', 'En una vÃ­a fuera de poblado en la que no exista zona peatonal ni arcÃ©n practicable, Â¿estÃ¡ permitido que un peatÃ³n circule por la calzada?', NULL, 'Cuando no existe zona peatonal ni arcÃ©n practicable, el peatÃ³n puede circular por la calzada adoptando las precauciones necesarias.', true, '2026-10-07 07:20:12.044', '2026-10-07 07:20:12.044');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-116', '{A1,A2,A,B,C,D}', 'Â¿CuÃ¡l es uno de los problemas que, debido al deterioro de las aptitudes psicofÃ­sicas, encuentran muchas personas mayores como peatones en las vÃ­as pÃºblicas?', NULL, 'El deterioro psicofÃ­sico puede dificultar la estimaciÃ³n de la velocidad de los vehÃ­culos que se aproximan.', true, '2026-10-07 07:20:12.06', '2026-10-07 07:20:12.06');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-117', '{B}', 'Acaba de comprar un turismo nuevo; Â¿cuÃ¡ndo debe presentarlo a la primera inspecciÃ³n tÃ©cnica reglamentaria?', NULL, 'La primera ITV de un turismo nuevo se realiza a los cuatro aÃ±os desde su matriculaciÃ³n.', true, '2026-10-07 07:20:12.077', '2026-10-07 07:20:12.077');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-118', '{A1,A2,A,B,C,D}', 'En las proximidades de vÃ­as de uso exclusivo de ciclos, Â¿quÃ© precauciones se deben tomar?', NULL, 'La proximidad de una vÃ­a exclusiva para ciclos exige extremar la precauciÃ³n, moderando la velocidad y deteniÃ©ndose si es necesario.', true, '2026-10-07 07:20:12.095', '2026-10-07 07:20:12.095');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-119', '{A1,A2,A,B,C,D}', 'Â¿EstÃ¡ permitido circular con un turismo por una vÃ­a en cuyo acceso estÃ¡ situada esta seÃ±al?', NULL, 'La seÃ±al identifica una vÃ­a reservada para ciclos, por la que un turismo no puede circular.', true, '2026-10-07 07:20:12.112', '2026-10-07 07:20:12.112');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-120', '{B}', 'Un turismo con el distintivo ambiental de la imagen, clasificado como ECO, Â¿estÃ¡ autorizado a circular por el carril VAO si su Ãºnico ocupante es el conductor?', NULL, 'Un vehÃ­culo ECO con un solo ocupante no puede utilizar el VAO salvo autorizaciÃ³n expresa mediante la seÃ±alizaciÃ³n correspondiente.', true, '2026-10-07 07:20:12.129', '2026-10-07 07:20:12.129');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-121', '{A1,A2,A,B,C,D}', 'El consumo de alcohol, aunque sea en pequeÃ±as cantidades...', NULL, 'Incluso pequeÃ±as cantidades de alcohol pueden deteriorar las capacidades necesarias para conducir con seguridad.', true, '2026-10-07 07:20:12.145', '2026-10-07 07:20:12.145');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-122', '{B}', 'Una persona mayor de edad, Â¿puede transportar a un pasajero en una bicicleta que, por construcciÃ³n, no pueda ser ocupada por mÃ¡s de una persona?', NULL, 'La normativa permite transportar a un menor de hasta siete aÃ±os en un asiento adicional homologado en las condiciones previstas.', true, '2026-10-07 07:20:12.163', '2026-10-07 07:20:12.163');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-123', '{A1,A2,A,B,C,D}', 'Delante de un vado, esta seÃ±al prohÃ­beâ€¦', NULL, 'La seÃ±al de vado prohÃ­be el estacionamiento, no necesariamente la parada.', true, '2026-10-07 07:20:12.181', '2026-10-07 07:20:12.181');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-124', '{B}', 'A falta de seÃ±alizaciÃ³n, Â¿cuÃ¡l es la velocidad mÃ¡xima permitida para una furgoneta cuando circule por una autovÃ­a que discurra dentro de poblado?', NULL, 'La velocidad mÃ¡xima indicada para una furgoneta en este supuesto es 80 km/h.', true, '2026-10-07 07:20:12.205', '2026-10-07 07:20:12.205');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-125', '{A1,A2,A,B,C,D}', 'Los menores de edad de estatura igual o inferior a 135 centÃ­metros deberÃ¡n utilizar sistemas de retenciÃ³n infantil homologados debidamente adaptados a...', NULL, 'El sistema de retenciÃ³n infantil debe estar adaptado a la talla y al peso del menor.', true, '2026-10-07 07:20:12.221', '2026-10-07 07:20:12.221');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-126', '{A1,A2,A,B,C,D}', 'En un carril reservado para uso exclusivo del transporte pÃºblico urbano, Â¿se puede estacionar?', NULL, 'El carril reservado al transporte pÃºblico no puede utilizarse para estacionar.', true, '2026-10-07 07:20:12.237', '2026-10-07 07:20:12.237');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-127', '{A1,A2,A}', 'Para los conductores y pasajeros de motocicletas, Â¿tiene importancia el vestuario a utilizar?', NULL, 'El equipamiento adecuado protege al motorista frente a las condiciones meteorolÃ³gicas y las consecuencias de una caÃ­da.', true, '2026-10-07 07:20:12.254', '2026-10-07 07:20:12.254');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-128', '{A1,A2,A,B,C,D}', 'Â¿Es posible ahorrar combustible evitando cambios de marcha innecesarios?', NULL, 'Una conducciÃ³n eficiente evita cambios de marcha innecesarios y puede reducir el consumo.', true, '2026-10-07 07:20:12.271', '2026-10-07 07:20:12.271');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-129', '{A1,A2,A,B,C,D}', 'Â¿QuÃ© debe hacer el conductor del vehÃ­culo ante las indicaciones que le realiza el agente del vehÃ­culo policial con la seÃ±al V-1 encendida?', NULL, 'Debe detenerse en el lugar indicado, en este caso en el lado derecho y delante del vehÃ­culo policial.', true, '2026-10-07 07:20:12.289', '2026-10-07 07:20:12.289');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-130', '{A1,A2,A,B,C,D}', 'En un accidente de trÃ¡fico se produce el efecto submarino cuando...', NULL, 'El efecto submarino ocurre cuando el cuerpo se desliza por debajo de la banda abdominal del cinturÃ³n.', true, '2026-10-07 07:20:12.305', '2026-10-07 07:20:12.305');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-131', '{A1,A2,A,B,C,D}', 'Si un conductor se encuentra esta seÃ±al, debe saber que en la prÃ³xima intersecciÃ³n...', NULL, 'La seÃ±al mostrada indica que en la prÃ³xima intersecciÃ³n se aplica la regla general de prioridad de paso.', true, '2026-10-07 07:20:12.322', '2026-10-07 07:20:12.322');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-132', '{A1,A2,A,B,C,D}', 'En un viaje largo es aconsejable descansar...', NULL, 'Realizar descansos aproximadamente cada dos horas ayuda a combatir la fatiga y mantener la atenciÃ³n.', true, '2026-10-07 07:20:12.341', '2026-10-07 07:20:12.341');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-133', '{A1,A2,A,B,C,D}', 'La seÃ±al de velocidad mÃ¡xima pintada sobre un carril, Â¿quÃ© indica?', NULL, 'La limitaciÃ³n pintada sobre un carril se aplica a los vehÃ­culos que circulen por ese carril.', true, '2026-10-07 07:20:12.357', '2026-10-07 07:20:12.357');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-134', '{B,C}', 'El conductor de un vehÃ­culo de distribuciÃ³n de mercancÃ­as Â¿cuÃ¡ndo podrÃ¡ circular por vÃ­a urbana sin utilizar el cinturÃ³n de seguridad?', NULL, 'Existe una excepciÃ³n para determinados conductores de vehÃ­culos de distribuciÃ³n cuando realizan sucesivas operaciones de carga y descarga en trayectos cortos dentro de poblado.', true, '2026-10-07 07:20:12.373', '2026-10-07 07:20:12.373');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-135', '{A1,A2,A,B,C,D}', 'Si un vehÃ­culo estacionado se incorpora a la circulaciÃ³n, Â¿tiene prioridad para realizar la maniobra?', NULL, 'La incorporaciÃ³n desde un estacionamiento debe hacerse cediendo el paso; seÃ±alizar no otorga prioridad.', true, '2026-10-07 07:20:12.39', '2026-10-07 07:20:12.39');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-136', '{A1,A2,A,B,C,D}', 'Esta seÃ±al indica la situaciÃ³n de un lugar donde se puede...', NULL, 'La seÃ±al identifica un apartadero de emergencia en un tÃºnel, destinado a apartar el vehÃ­culo y dejar libre el paso.', true, '2026-10-07 07:20:12.41', '2026-10-07 07:20:12.41');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-137', '{A1,A2,A,B,C,D}', 'Â¿CÃ³mo se llama la distancia que recorre un vehÃ­culo desde que el conductor percibe un estÃ­mulo hasta que se responde al mismo?', NULL, 'Es la distancia de reacciÃ³n: la recorrida desde que se percibe el estÃ­mulo hasta que se inicia la respuesta.', true, '2026-10-07 07:20:12.43', '2026-10-07 07:20:12.43');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-138', '{B}', 'Â¿CuÃ¡l es, como norma general, la velocidad mÃ¡xima a la que le estÃ¡ permitido circular a un turismo por una carretera convencional?', NULL, 'La velocidad mÃ¡xima general de los turismos en carretera convencional es 90 km/h, salvo seÃ±alizaciÃ³n especÃ­fica.', true, '2026-10-07 07:20:12.452', '2026-10-07 07:20:12.452');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-139', '{A1,A2,A,B,C,D}', 'Dos vehÃ­culos del mismo tipo se encuentran justo en la mitad de este estrechamiento, en el que la prioridad no estÃ¡ seÃ±alizada. Â¿CuÃ¡l de ellos tendrÃ¡ preferencia de paso?', NULL, 'Si son vehÃ­culos del mismo tipo y estÃ¡n en la mitad del estrechamiento, tiene preferencia el de mayores dimensiones o MMA.', true, '2026-10-07 07:20:12.47', '2026-10-07 07:20:12.47');
INSERT INTO public.preguntas_dgt (id, licencia, enunciado, "imagenRuta", explicacion, activa, "createdAt", "updatedAt") VALUES ('pregunta-dgt-b-140', '{A1,A2,A,B,C,D}', 'Cuando no se puede circular hacia adelante ni cambiar de direcciÃ³n o sentido de la marcha, Â¿se permite circular marcha atrÃ¡s?', NULL, 'La marcha atrÃ¡s se permite excepcionalmente y debe limitarse al recorrido mÃ­nimo indispensable.', true, '2026-10-07 07:20:12.487', '2026-10-07 07:20:12.487');
